function showSession(current,needsSetup=false){dashboardDraft={};hpDrafts.clear();user=current;canManage=!!current&&['admin','manager'].includes(current.role);$('setup').classList.toggle('hidden',!needsSetup);$('login').classList.toggle('hidden',!!current||needsSetup);$('session').classList.toggle('hidden',!current);$('accounts').classList.toggle('hidden',!current);$('adminControls').classList.toggle('hidden',current?.role!=='admin');$('reports').classList.toggle('hidden',!current);$('weeklySection').classList.toggle('hidden',!current);$('reminders').classList.toggle('hidden',!canManage);for(const id of ['periodEnd','savePeriodEnd','timelineStart','timelineEnd','saveTimeline'])$(id).disabled=!canManage;$('newRole').disabled=current?.role!=='admin';if(current?.role!=='admin')$('newRole').value='hp';$('userLabel').textContent=current?`${current.username} · ${current.role==='admin'?'Admin':current.role==='manager'?'Team manager':'HP'}`:'';clearInterval(refreshTimer);if(current){refresh();if(current.role==='admin')loadAdminUsers();refreshTimer=setInterval(()=>{if(!hasDrafts()&&!document.activeElement?.closest('#weeklySection,#reminders,#scoreTable,#hpTable,#monthlyPlan'))refresh()},15000)}else{dashboard={};hps.clear();window.reportHistory=[];weekData=[];reminderData=[];reminderDays=[];renderWeeks();renderReminders();renderDashboard();renderHpSelect();renderScoreboard()}}
