$('signOut').addEventListener('click',async()=>{await api('logout').catch(()=>{});showSession(null)});
$('createAccount').addEventListener('click',async()=>{const username=$('newCode').value.trim().toLowerCase(),name=$('newName').value.trim(),password=$('newPassword').value,role=$('newRole').value;const button=$('createAccount');button.disabled=true;try{await api('createUser',{username,name,password,role});message('accountMessage',`${username} created. Share the username and password privately.`,'success');$('newCode').value=$('newName').value=$('newPassword').value='';await refresh();if(user.role==='admin')await loadAdminUsers()}catch(error){message('accountMessage',error.message,'error')}button.disabled=false});
$('saveTimeline').addEventListener('click',async()=>{try{await api('settings',{timeline_start:$('timelineStart').value,timeline_end:$('timelineEnd').value});await refresh();message('reportMessage','Timeline saved.','success')}catch(error){message('reportMessage',error.message,'error')}});
$('savePeriodEnd').addEventListener('click',async()=>{try{await api('settings',{period_end:$('periodEnd').value});await refresh();message('reportMessage','Month-end date saved.','success')}catch(error){message('reportMessage',error.message,'error')}});
$('saveWeekDates').addEventListener('click',async()=>{const ends=[...$('weekGrid').querySelectorAll('.week-end')].map(input=>input.value);try{await api('setWeekEnds',{start:$('weekPeriodStart').value,ends});await refresh();message('weekMessage','Period and week endings saved.','success')}catch(error){message('weekMessage',error.message,'error')}});
$('reminderRepeat').addEventListener('change',()=>{$('repeatUnit').textContent=$('reminderRepeat').value==='daily'?'day(s)':$('reminderRepeat').value==='weekly'?'week(s)':$('reminderRepeat').value==='monthly'?'month(s)':'time'});
$('cancelReminder').addEventListener('click',clearReminderForm);
$('saveReminder').addEventListener('click',async()=>{const old=reminderData.find(item=>item.id===editingReminderId),lines=$('reminderItems').value.split('\n').map(text=>text.trim()).filter(Boolean),checklist=lines.map((text,i)=>({id:old?.checklist[i]?.id||crypto.randomUUID(),text}));try{await api('saveReminder',{id:editingReminderId||undefined,title:$('reminderTitle').value.trim(),checklist,repeat_type:$('reminderRepeat').value,repeat_interval:Number($('reminderInterval').value),starts_on:$('reminderStart').value,ends_on:$('reminderEnd').value||null});clearReminderForm();await refresh();message('reminderMessage','Reminder saved.','success')}catch(error){message('reminderMessage',error.message,'error')}});
function csvCell(v){return `"${String(v??'').replaceAll('"','""')}"`}
function reportRows(){const lines=[['Period','HP code','HP name','Row','Target','Actual']];function add(period,values,code,name,prefix,labels,hidden=[]){labels.forEach((label,i)=>{if(!hidden.includes(i))lines.push([period,code,name,values[`${prefix}-${i}-label`]||label,values[`${prefix}-${i}-target`]||'',values[`${prefix}-${i}-actual`]||''])})}add('Current',teamDashboardValues(dashboard,hps.values()),'','Team dashboard','score',dashboardRows);for(const [code,hp] of hps)add('Current',hp.metrics,code,hp.name,'hp',hpRows,hp.hidden_rows||[]);for(const report of window.reportHistory||[]){add(report.period_end,teamDashboardValues(report.dashboard_values,report.hp_values||[]),'','Team dashboard','score',dashboardRows);for(const hp of report.hp_values||[])add(report.period_end,hp.metrics,hp.code,hp.name,'hp',hpRows,hp.hidden_rows||[])}return lines}
$('downloadReport').addEventListener('click',()=>{const csv=reportRows().map(row=>row.map(csvCell).join(',')).join('\r\n'),link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));link.download='jiha-team-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});
$('printReport').addEventListener('click',()=>{const section=$('printData'),heading=document.createElement('h1'),table=document.createElement('table');heading.textContent='Jiha Team Report';section.replaceChildren(heading);for(const [index,row] of reportRows().entries()){const tr=document.createElement('tr');for(const value of row){const cell=document.createElement(index?'td':'th');cell.textContent=value;tr.append(cell)}table.append(tr)}section.append(table);window.print()});
$('today').textContent=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date());clearReminderForm();setInterval(updateCountdowns,1000);renderDashboard();renderHpSelect();renderScoreboard();api('me').then(({user,needsSetup})=>showSession(user,needsSetup)).catch(error=>message('authMessage',error.message,'error'));
